"""Extensively and excruciatingly done.
Deep elaboration of every perspective, every how/why/when, every phase.
"""
from typing import Dict, Any

class Excruciating:
    def full(self, brief: str) -> Dict[str, Any]:
        return {
            "brief": brief,
            "designer_perspective": {
                "how_detailed": "Map every player verb to a systemic state change. Inventory weight and rarity create meaningful constraints. Combat must consume resources and produce progression currency that is immediately legible. Progression must gate both new verbs and narrative beats so that mechanical growth and story advancement are the same act.",
                "why_detailed": "Players retain when the next action is fun. They master when systems talk to each other. They find purpose when later play recontextualizes earlier choices. Without interlock, the game is a collection of features instead of an experience.",
                "when_detailed": "First 10 minutes: one verb, one clear reward. Next 50 minutes: two systems begin to interact. After hour two: full interlock and narrative stakes that make the early loop feel deeper in retrospect."
            },
            "narrative_perspective": {
                "how_detailed": "State the protagonist want in concrete external terms in the first scenes. Reveal the internal need through pressure, not exposition. Construct the midpoint so the want becomes achievable only by confronting the need. Design the climax as a choice that cannot satisfy both.",
                "why_detailed": "Audience investment requires a clear desire and a visible cost. Theme is not stated; it is the residue of what the character is willing to pay or refuses to pay.",
                "when_detailed": "Act 1 establishes want and world rules. Midpoint delivers a false victory or reversal that exposes the real problem. Act 3 forces the irreversible decision."
            },
            "cinematic_perspective": {
                "how_detailed": "Open with wide shots that teach geography. Move to medium for performance and relationship. Use close-ups only for emotional peaks. Move the camera only when following character intent, revealing new information, or heightening feeling. Key light models form, fill keeps eyes readable, rim separates subject from background.",
                "why_detailed": "If the audience is confused about space or unsure how to feel, immersion breaks. Motivated camera and clear shot progression prevent that.",
                "when_detailed": "Dialogue scenes hold longer with stable framing. Action scenes cut shorter and on movement. Reveals hold the frame then accelerate."
            },
            "audio_perspective": {
                "how_detailed": "Assign every major character and theme a short, identifiable melodic cell. Allow cells to combine, fragment, and transform. Scale orchestration from sparse to full according to dramatic weight. Lock every hit to picture. Hide transitions inside action or dialogue.",
                "why_detailed": "Music tells the audience how to feel before the image fully registers and creates subconscious continuity across hours.",
                "when_detailed": "Character entrance: cell under picture. Rising action: development and combination. Climax: full statement. Resolution: cell resolved or inverted."
            },
            "excruciating": True,
            "extensive": True,
            "highest_caliber": True
        }
